'use strict';

// MODULES //

var abs = require( '@stdlib/math/base/special/abs' );
var round = require( '@stdlib/math/base/special/round' );
var isInteger = require( '@stdlib/math/base/assert/is-integer' );
var gamma = require( '@stdlib/math/base/special/gamma' );
var isNegativeInteger = require( '@stdlib/math/base/assert/is-negative-integer' );
var isNonPositiveInteger = require( '@stdlib/math/base/assert/is-nonpositive-integer' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var UINT32_MAX = require( '@stdlib/constants/uint32/max' );
// hyt2f1(double a, double b, double c, double x, double *loss);
// hys2f1(double a, double b, double c, double x, double *loss);
// hyp2f1ra(double a, double b, double c, double x, double *loss);

// VARIABLES //

var EPS = 1.0e-13;
var ETHRESH = 1.0e-12;
var MAX_ITERATIONS = 10000;


// MAIN //

/**
* Evaluates the Gaussian hypergeometric function.
*
* @param {number} a - input value
* @param {number} b - input value
* @param {number} c - input value
* @param {number} x - input value
* @returns {number} function value
*
* @example
* var v = hyp2f1( 1.0, 1.0, 1.0, 0.0 );
* // returns 1.0
*/
function hyp2f1( a, b, c, x ) {

	var ret, y;
	err = 0.0;
	ax = abs( x );
	s = 1.0 - x;
	ia = round( a );
	ib = round( b );

	if( x == 0.0 ) {
		return 1.0;
	}

	d = c - a - b;
	id = round(d);

	if ( ( a == 0.0 || b == 0.0 ) && c != 0.0 ) {
		return 1.0;
	}

	neg_int_a = isNonPositiveInteger( a );
	neg_int_b = isNonPositiveInteger( b );
	isIntD = isInteger( d );

	if (d <= -1 && !(!isIntD && s < 0) && !(neg_int_a || neg_int_b)) {
		y = hyp2f1(c - a, c - b, c, x);
		return pow(s, d) * y.value;
	}

	if (d <= 0.0 && x == 1.0 && !(neg_int_a || neg_int_b)) {
		return PINF;
	}

	if (ax < 1.0 || x == -1.0) {
		if (b==c) {
			y = pow(s, -a);
			return y;
		}
		if (a==c) {
			y = pow(s, -b);
			return y;
		}
	}

	neg_int_c = isNonPositiveInteger( c );
	if (neg_int_c) {
		if (neg_int_a && (ia > ic)) {
			y = hyt2f1(a, b, c, x, err);
			return y.value;
		}
		if (neg_int_b && (ib > ic)) {
			y = hyt2f1(a, b, c, x, err);
			return y.value;
		}
		return PINF;
	}

	if (neg_int_a || neg_int_b)	{
		y = hyt2f1(a, b, c, x, err);
		return y.value;
	}

	t1 = abs(b-a);
    if (x < -2.0 && !isInteger(t1)) {
		/* This transform has a pole for b-a integer, and
		 * may produce large cancellation errors for |1/x| close 1
		 */
		p = hyp2f1(a, 1 - c + a, 1 - b + a, 1.0 / x);
		q = hyp2f1(b, 1 - c + b, 1 - a + b, 1.0 / x);
		pVal = p.value;
		qVal = q.value;
		pVal *= pow(-x, -a);
		qVal *= pow(-x, -b);
		t1 = gamma(c);
		s = t1 * gamma(b - a) / (gamma(b) * gamma(c - a));
		y = t1 * gamma(a - b) / (gamma(a) * gamma(c - b));
		return s * pVal + y * qVal;
	}

	else if (x < -1.0) {
		if (abs(a) < abs(b)) {
			y = hyp2f1(a, c - b, c, x / (x - 1));
			return pow(s, -a) * y.value;
		}
		else {
			y = hyp2f1(b, c - a, c, x / (x - 1));
			return pow(s, -b) * y.value;
		}
	}

	if (ax > 1.0) {
		return PINF;
	}

    p = c - a;
	r = c - b;
	neg_int_ca_or_cb = isNonPositiveInteger(p) || isNonPositiveInteger(r);

    if (ax == 1.0) {
		if (x > 0.0) {
			if (neg_int_ca_or_cb) {
				if (d >= 0.0) {
					y = hys2f1(c - a, c - b, c, x, err);
					return pow(s, d) * y.value;
				}
				else {
					return PINF;
				}
			}
			if (d <= 0.0) {
				return PINF;
			}
			y = gamma(c) * gamma(d) / (gamma(p) * gamma(r));
			return y;
		}
		if (d <= -1.0) {
			return PINF;
		}
	}

    if (d < 0.0) {
		y = hyt2f1(a, b, c, x, err);
		if (y.error < ETHRESH) {
			return y.value;
		}
		err = 0.0;
		aid = 2 - id;
		e = c + aid;
		d2 = hyp2f1(a, b, e, x);
		d1 = hyp2f1(a, b, e + 1.0, x);
		q = a + b + 1.0;
		for (i = 0; i < aid; i++) {
			r = e - 1.0;
			y = (e * (r - (2.0 * e - q) * x) * d2 + (e - a) * (e - b) * x * d1) / (e * r * s);
			e = r;
			d1 = d2;
			d2 = y;
		}
		return y;
	}

	if( neg_int_ca_or_cb ) {
		y = hys2f1(c - a, c - b, c, x, err);
		return pow(s, d) * y.value;
	}
}

module.exports = hyp2f1;
